files.money.py:
def split_amount(cents, parts):
    """Splits an amount in cents into equal shares."""
    return [cents // parts] * parts

files.tests/test_money.py:
from money import split_amount


def test_even_split():
    assert split_amount(90, 3) == [30, 30, 30]


def test_one_part():
    assert split_amount(55, 1) == [55]


def test_split_amount_shares_add_up_to_total():
    shares = split_amount(90, 3)
    assert sum(shares) == 90


def test_split_amount_leftover_cents_go_to_first_shares():
    shares = split_amount(60, 3)
    assert shares == sorted(shares, reverse=True)
    assert len(shares) == 3


def test_split_amount_returns_requested_number_of_parts():
    assert len(split_amount(100, 3)) == 3

